declare const _brand_flag: unique symbol;
/**
 * Simulate nominal typing within TypeScript's structurally-typed system,
 * for cases where a type can't be reliable defined using structural typing.
 * Google "Branded Types" for reference.
 */
export type Branded<Type, BrandFlag extends string> = Type & { [_brand_flag]: BrandFlag };

/** Returns the value if it's "object-like" (any object or array, but not null), or returns null. */
export function asObject<T>(val: T): (T & object) | null {
  return val !== null && typeof val === 'object' ? val : null;
}
